widget.solution:
def parse_qty(text):
    qty = int(text)
    if qty <= 0:
        raise ValueError(f"quantity must be positive: {text}")
    return qty


def load_orders(lines):
    orders = []
    rejected = 0
    for line in lines:
        try:
            ticker, text = line.split(",")
            orders.append((ticker, parse_qty(text)))
        except ValueError:
            rejected += 1
    return orders, rejected

